function pf_defs():string{return '<svg class="pf-defs" width="0" height="0" aria-hidden="true" focusable="false"><defs>'.PF_DEFS.'</defs></svg>';}
function pf_kid(string $vb='96 18 134 180',string $cls=''):string{return '<svg class="pf-kid '.$cls.'" viewBox="'.$vb.'" aria-hidden="true">'.PF_KID.'</svg>';}
function pf_pts(float $cx,float $cy,float $R,float $r,int $n=5):string{$p=[];for($i=0;$i<$n*2;$i++){$a=deg2rad(-90+$i*180/$n);$rr=$i%2?$r:$R;$p[]=round($cx+$rr*cos($a),1).','.round($cy+$rr*sin($a),1);}return implode(' ',$p);}
function pf_sparkle(float $x,float $y,float $s,string $c,string $cls='pf-tw'):string{return '<path class="'.$cls.'" d="M'.$x.' '.($y-$s).'Q'.($x+$s*.18).' '.($y-$s*.18).' '.($x+$s).' '.$y.'Q'.($x+$s*.18).' '.($y+$s*.18).' '.$x.' '.($y+$s).'Q'.($x-$s*.18).' '.($y+$s*.18).' '.($x-$s).' '.$y.'Q'.($x-$s*.18).' '.($y-$s*.18).' '.$x.' '.($y-$s).'z" fill="'.$c.'"/>';}
function pf_ribbon(string $text,int $w=200,string $fill='pf-red'):string{
 return '<svg viewBox="0 0 '.$w.' 44" width="'.$w.'" class="pf-ribbon" role="img" aria-label="'.e($text).'"><path d="M0 12h22v26H0l8-13z" fill="#a8281a"/><path d="M'.$w.' 12h-22v26h22l-8-13z" fill="#a8281a"/><path d="M14 4h'.($w-28).'v30H14z" fill="url(#'.$fill.')"/><path d="M14 34l8 6v-6zM'.($w-14).' 34l-8 6v-6z" fill="#7a1c11"/><text x="'.($w/2).'" y="25" text-anchor="middle" font-family="Poppins,sans-serif" font-weight="800" font-size="14" fill="#fff" letter-spacing="1">'.e($text).'</text></svg>';
}
function pf_badge_icon(string $rule):string{
 return match($rule){
  'lesson','reading_book'=>'<path d="M50 58v20M37 55c5-1 9 0 13 3 4-3 8-4 13-3v20c-5-1-9 0-13 3-4-3-8-4-13-3z" fill="#fff" stroke="#fff" stroke-width="2" stroke-linejoin="round"/><path d="M50 58v20" stroke="rgba(0,0,0,.25)" stroke-width="2"/>',
  'reading'=>'<rect x="45" y="50" width="10" height="18" rx="5" fill="#fff"/><path d="M40 63a10 10 0 0 0 20 0M50 73v6M45 80h10" stroke="#fff" stroke-width="3" stroke-linecap="round" fill="none"/>',
  'xp'=>'<path d="M54 49 41 68h9l-3 14 13-19h-9z" fill="#fff"/>',
  'streak'=>'<path d="M51 50c3 9-8 8-5 16 2-1 3-3 3-5 8 6 7 17-1 17s-13-9-6-17c0 4 2 5 4 5-3-6 5-9 5-16z" fill="#fff"/>',
  'level'=>'<path d="M36 76h28l3-18-10 8-7-12-7 12-10-8z" fill="#fff" stroke="#fff" stroke-width="1.5" stroke-linejoin="round"/>',
  'activity'=>'<path d="M39 66l8 8 15-16" stroke="#fff" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" fill="none"/>',
  default=>'<polygon points="'.pf_pts(50,67,14,6).'" fill="#fff"/>',
 };
}
function pf_badge_color(string $rule):array{
 return match($rule){'lesson'=>['pf-blue','pf-blue'],'reading'=>['pf-purple','pf-purple'],'streak'=>['pf-orange','pf-orange'],'level','activity'=>['pf-green','pf-green'],default=>['pf-goldface','pf-gold']};
}
function pf_medal(string $rule,int $size=96,bool $earned=true,bool $tails=true):string{
 [$face,$ring]=$earned?pf_badge_color($rule):['pf-grey','pf-grey'];$sc='';
 for($a=0;$a<360;$a+=20)$sc.='<circle cx="'.round(50+33*cos(deg2rad($a)),1).'" cy="'.round(66+33*sin(deg2rad($a)),1).'" r="5" fill="url(#'.$ring.')"/>';
 $tl=$tails?($earned?'<path d="M30 6h16l8 34H38z" fill="url(#pf-red)"/><path d="M70 6H54l-8 34h16z" fill="url(#pf-green)"/>':'<path d="M30 6h16l8 34H38zM70 6H54l-8 34h16z" fill="#d5d9d5"/>').'<path d="M30 6h16l2 8H32z" fill="#000" opacity=".12"/>':'';
 $icon=$earned?pf_badge_icon($rule):'<text x="50" y="76" text-anchor="middle" font-family="Poppins,sans-serif" font-weight="800" font-size="26" fill="#9aa39a">?</text>';
 return '<svg class="pf-medal-svg" viewBox="0 0 100 106" width="'.$size.'" height="'.round($size*1.06).'" aria-hidden="true">'.$tl.$sc.'<circle cx="50" cy="66" r="33" fill="url(#'.$ring.')"/><circle cx="50" cy="66" r="25" fill="url(#'.$face.')"/><circle cx="50" cy="66" r="25" fill="none" stroke="#fff" stroke-opacity=".55" stroke-width="1.5" stroke-dasharray="2 3"/>'.$icon.($earned?'<path d="M30 52a24 24 0 0 1 22-11" stroke="#fff" stroke-opacity=".7" stroke-width="3" stroke-linecap="round" fill="none"/>':'').'</svg>';
}
function pf_star(string $cls):string{return '<svg viewBox="0 0 60 60" class="pf-star '.$cls.'" aria-hidden="true"><polygon points="'.pf_pts(30,32,27,12).'" fill="url(#pf-gold)" stroke="#c98200" stroke-width="2" stroke-linejoin="round"/><polygon points="'.pf_pts(30,32,17,7.5).'" fill="#fff" opacity=".28"/><path d="M19 22l5-3" stroke="#fff" stroke-width="3" stroke-linecap="round" opacity=".85"/></svg>';}
function pf_confetti(int $n=26):string{$s='';for($i=0;$i<$n;$i++)$s.='<i class="pf-conf pf-c'.($i%4).'"></i>';return '<div class="pf-confetti" aria-hidden="true">'.$s.'</div>';}
const PF_COIN='<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><circle cx="12" cy="12" r="10" fill="url(#pf-gold)" stroke="#c98200" stroke-width="1.5"/><path d="m13 6-5 7h4l-1 5 5-7h-4z" fill="#fff"/></svg>';

/* 1 · Lesson complete celebration */
function pf_lesson_celebration(int $lid,int $pid,bool $finished):string{
 $xp=(int)val('SELECT COALESCE(SUM(x.amount),0) FROM xp_transactions x JOIN activities a ON a.id=x.activity_id WHERE x.pupil_id=? AND a.lesson_id=?',[$pid,$lid]);
 $possible=(int)val('SELECT COALESCE(SUM(xp_reward),0) FROM activities WHERE lesson_id=? AND published=1',[$lid]);
 $r=$possible>0?$xp/$possible:1;$stars=$r>=.9?3:2;
 $st='';for($i=1;$i<=3;$i++)$st.=pf_star('pf-s'.$i.($i>$stars?' pf-star-off':''));
 return '<div class="pf-celebrate" data-pf-play role="img" aria-label="'.$stars.' out of 3 stars. You earned '.$xp.' XP."><div class="pf-burst"></div>'.pf_confetti().'<div class="pf-stars">'.$st.'</div>'.pf_kid('96 18 134 180','pf-jumper').'<div class="pf-xpchip">'.PF_COIN.'+<span data-count="'.$xp.'">'.$xp.'</span> XP</div>'.pf_ribbon($finished?'LESSON COMPLETE!':'YOU DID IT!',196).'</div>';
}

/* 2 + 3 · Badge and level celebrations, shown once each */
function pf_seen(int $pid):?array{$v=val('SELECT setting_value FROM settings WHERE setting_key=?',['pupil_seen_'.$pid]);return $v===null||$v===false?null:(json_decode((string)$v,true)?:['b'=>[],'l'=>[]]);}
function pf_save_seen(int $pid,array $s):void{q('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)',['pupil_seen_'.$pid,json_encode(['b'=>array_values(array_unique(array_map('intval',$s['b']))),'l'=>array_values(array_unique(array_map('intval',$s['l'])))])]);}
function pf_available_levels(int $pid):array{$ids=[];foreach(rows('SELECT id FROM bulig_levels ORDER BY id') as $l)if(level_available($pid,(int)$l['id']))$ids[]=(int)$l['id'];return $ids;}
function pupil_celebrations(array $u):string{
 $pid=(int)$u['id'];$badges=rows('SELECT b.* FROM pupil_badges p JOIN badges b ON b.id=p.badge_id WHERE p.pupil_id=? ORDER BY p.earned_at,b.id',[$pid]);$levels=pf_available_levels($pid);
 $seen=pf_seen($pid);
 if($seen===null){pf_save_seen($pid,['b'=>array_column($badges,'id'),'l'=>$levels]);return '';}
 $start=(int)val('SELECT level_id FROM pupil_level_assignments WHERE pupil_id=?',[$pid]);$out='';$shown=0;
 foreach($badges as $b){if(in_array((int)$b['id'],$seen['b'],true))continue;$seen['b'][]=(int)$b['id'];if($shown++>=3)continue;
  $out.='<div class="pw-overlay pf-cel" data-pf-overlay hidden role="dialog" aria-modal="true" aria-labelledby="pf-b'.$b['id'].'"><div class="pw-panel pf-cel-panel"><button type="button" class="pw-close" data-welcome-close aria-label="Close">'.icon('close').'</button><div class="pf-badge-stage" aria-hidden="true"><div class="pf-burst"></div><svg class="pf-spk" viewBox="0 0 226 200" preserveAspectRatio="xMidYMid slice">'.pf_sparkle(30,40,9,'#f6c02c').pf_sparkle(196,60,7,'#ff8fab','pf-tw pf-t1').pf_sparkle(46,150,6,'#7cc4ff','pf-tw pf-t2').pf_sparkle(184,150,8,'#f6c02c','pf-tw pf-t1').pf_sparkle(170,24,5,'#4cb86b','pf-tw pf-t2').'</svg><div class="pf-medal-pop">'.pf_medal($b['rule_type'],116).'<span class="pf-shine"></span></div></div>'.pf_ribbon(strtoupper($b['title']),min(300,max(170,22+mb_strlen($b['title'])*11)),'pf-green').'<span class="pw-eyebrow">YOU EARNED A NEW BADGE!</span><h2 id="pf-b'.$b['id'].'">'.e($b['title']).'</h2><p class="pw-msg">'.e($b['description']).'</p><div class="pw-actions"><a class="btn primary" href="?page=achievements">'.icon('star').'See my badges</a><button type="button" class="btn secondary" data-welcome-close>Keep going</button></div></div></div>';}
 foreach($levels as $id){if(in_array($id,$seen['l'],true))continue;$seen['l'][]=$id;if($id===$start||$shown++>=3)continue;$label=level_label($id);$num=str_replace('Level ','',$label);$title=(string)val('SELECT title FROM bulig_levels WHERE id=?',[$id]);
  $out.='<div class="pw-overlay pf-cel" data-pf-overlay hidden role="dialog" aria-modal="true" aria-labelledby="pf-l'.$id.'"><div class="pw-panel pf-cel-panel"><button type="button" class="pw-close" data-welcome-close aria-label="Close">'.icon('close').'</button><div class="pf-gate" aria-hidden="true"><div class="pf-gate-light"></div><div class="pf-gate-inside"><svg viewBox="0 0 150 180" preserveAspectRatio="none"><path d="M0 140q40-24 75-8t75-6v54H0z" fill="#89cf73"/><path d="M60 180q10-40 15-48 5 8 15 48z" fill="#f2dca4"/></svg></div><div class="pf-doors"><div class="pf-door pf-dl"></div><div class="pf-door pf-dr"></div></div><svg class="pf-arch" width="330" height="200" viewBox="0 0 330 200"><path d="M70 200V95a95 95 0 0 1 190 0v105h-15V95a80 80 0 0 0-160 0v105z" fill="url(#pf-stone)" stroke="#8d977f" stroke-width="2"/><path d="M90 200V95a75 75 0 0 1 150 0v105" fill="none" stroke="#8d977f" stroke-width="3"/><path d="M120 12l8 16M210 12l-8 16M92 40l13 11M238 40l-13 11M75 75l16 5M255 75l-16 5M70 120h20M240 120h20M70 160h20M240 160h20" stroke="#8d977f" stroke-width="2"/><rect x="145" y="2" width="40" height="22" rx="5" fill="url(#pf-gold)" stroke="#c98200" stroke-width="1.5"/><text x="165" y="18" text-anchor="middle" font-family="Poppins,sans-serif" font-weight="800" font-size="13" fill="#7a4f00">'.e($num).'</text></svg><svg class="pf-gate-lock" viewBox="0 0 30 34" width="46"><path d="M8 15V10a7 7 0 0 1 14 0v5" stroke="#9aa39a" stroke-width="3.6" fill="none"/><rect x="3" y="14" width="24" height="18" rx="5" fill="url(#pf-gold)"/><circle cx="15" cy="22" r="3" fill="#7a5a00" opacity=".7"/><path d="M15 23v5" stroke="#7a5a00" stroke-width="2.4" stroke-linecap="round" opacity=".7"/></svg>'.pf_kid('96 18 134 180','pf-walker').'</div>'.pf_ribbon(strtoupper($label).' UNLOCKED!',230).'<span class="pw-eyebrow">GREAT READING!</span><h2 id="pf-l'.$id.'">'.e($label).' is open!</h2><p class="pw-msg">'.e($title).'</p><div class="pw-actions"><a class="btn primary" href="?page=dashboard&amp;level='.$id.'#level'.$id.'-path">'.icon('arrow').'Open '.e($label).'</a><button type="button" class="btn secondary" data-welcome-close>Later</button></div></div></div>';}
 pf_save_seen($pid,$seen);return $out;
}

/* 4 · Reading garden */
function pf_plant(int $stage):string{
 $h=[0=>14,1=>26,2=>52,3=>76][$stage];$s='<svg viewBox="0 0 120 140" class="pf-plant pf-st'.$stage.'" aria-hidden="true"><ellipse cx="60" cy="132" rx="36" ry="5" fill="#2a5a2a" opacity=".2"/><path class="pf-stem" d="M60 104C58 '.(104-$h*.4).' 63 '.(104-$h*.7).' 60 '.(104-$h).'" stroke="#3e9a4a" stroke-width="5" stroke-linecap="round" fill="none"/>';
 $lv=$stage===0?[[60,94,-1,0,.6],[60,92,1,1,.6]]:[[60,96,-1,0,.95],[60,92,1,1,.95]];
 if($stage>=2){$lv[]=[60,74,-1,2,.85];$lv[]=[60,68,1,3,.85];}
 if($stage>=3)$lv[]=[60,50,-1,4,.85];
 foreach($lv as [$x,$y,$d,$i,$sc])$s.='<g class="pf-leaf pf-l'.$i.'" transform="translate('.$x.' '.$y.') scale('.($d*$sc).' '.$sc.')"><path d="M0 0q16-18 34-8q-14 18-34 8z" fill="url(#pf-leaf)" stroke="#2a7a40" stroke-width="1.2"/><path d="M2 0q14-6 28-7" stroke="#d8f5cf" stroke-width="1.2" fill="none"/></g>';
 if($stage===3){$s.='<g class="pf-bloom">';for($a=0;$a<360;$a+=60)$s.='<ellipse cx="60" cy="16" rx="7" ry="11" fill="url(#pf-petal)" transform="rotate('.$a.' 60 28)"/>';$s.='<circle cx="60" cy="28" r="7" fill="url(#pf-sun)" stroke="#e09a00" stroke-width="1"/></g>';}
 return $s.'<path d="M34 104h52l-7 30H41z" fill="url(#pf-pot)"/><rect x="29" y="98" width="62" height="11" rx="4" fill="#f0a072"/><rect x="29" y="98" width="62" height="4" rx="2" fill="#ffc29d"/><path d="M42 114q4 10 3 16" stroke="#fff" stroke-opacity=".35" stroke-width="3" stroke-linecap="round" fill="none"/></svg>';
}
function pf_garden(int $done):string{
 $stage=$done>=12?3:($done>=5?2:($done>=1?1:0));$goal=[0=>1,1=>5,2=>12][$stage]??null;
 $note=$goal?($goal-$done).' more '.($goal-$done===1?'lesson':'lessons').' to '.($stage===2?'bloom':'grow'):'Your garden is in full bloom!';
 return '<div class="adventure-art pf-garden-art"><div class="pf-garden" data-pf-play role="img" aria-label="Your reading garden. '.$done.' lessons done. '.e($note).'"><span class="pf-gsun"></span>'.($stage<3?'<span class="pf-drops"><i></i><i></i><i></i></span>':'<svg class="pf-bfly" viewBox="-20 -16 40 32" aria-hidden="true"><g class="pf-wing"><path d="M0 0c-10-12-20-4-14 4c-8 2-6 12 4 8z" fill="#9b7bff"/><path d="M0 0c10-12 20-4 14 4c8 2 6 12-4 8z" fill="#c3a2ff"/></g><path d="M0-4v14" stroke="#3b2a20" stroke-width="2.4" stroke-linecap="round"/></svg>').pf_plant($stage).'</div><span class="adventure-note pf-gnote">'.icon('star').'My reading garden · '.e($note).'</span></div>';
}

/* 6 · Streak flame and week */
function pf_streak(int $pid,int $streak):string{
 $days=array_column(rows('SELECT day FROM learning_days WHERE pupil_id=? AND day>=?',[$pid,date('Y-m-d',strtotime('-6 days'))]),'day');$days=array_map(fn($d)=>substr((string)$d,0,10),$days);
 $size=$streak>=7?'pf-fl3':($streak>=3?'pf-fl2':($streak>=1?'pf-fl1':'pf-fl0'));$today=date('Y-m-d');
 $w='';for($i=6;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i days"));$on=in_array($d,$days,true);$w.='<span class="'.($on?'on':'').($d===$today?' today':'').'"><i></i>'.substr(date('D',strtotime($d)),0,1).'</span>';}
 $flame='<svg viewBox="0 0 80 100" class="pf-flame '.$size.'" aria-hidden="true"><ellipse cx="40" cy="70" rx="40" ry="34" fill="url(#pf-fglow)"/><path class="pf-fo" d="M40 4c8 22-18 24-10 44 3-3 6-8 6-12 22 14 20 56-4 56S2 72 22 46c0 10 5 12 9 12-7-16 11-28 9-54z" fill="url(#pf-fo)"/><path class="pf-fi" d="M40 52c3 10-8 12-5 20 2-1 3-3 3-5 10 6 8 24-2 24s-14-11-6-19c0 4 2 5 4 5-3-8 6-13 6-25z" fill="url(#pf-fi)"/><circle class="pf-em pf-e1" cx="30" cy="30" r="2.4" fill="#ffb347"/><circle class="pf-em pf-e2" cx="52" cy="26" r="2" fill="#ffd447"/><circle class="pf-em pf-e3" cx="44" cy="18" r="1.8" fill="#ff8a1f"/></svg>';
 return $flame.(in_array($today,$days,true)&&$streak>0?'<span class="pf-plus" data-pf-plus="'.$today.'" hidden>+1 day</span>':'').'<div class="pf-week" aria-label="Days you learned this week">'.$w.'</div>';
}

/* 7 · Progress ring for the current level card */
function pf_ring(int $pct):string{$pct=max(0,min(100,$pct));return '<span class="pf-ring" aria-label="'.$pct.'% complete"><svg viewBox="0 0 44 44" aria-hidden="true"><circle cx="22" cy="22" r="18" fill="none" stroke="#e7efe5" stroke-width="5"/><circle class="pf-ring-fill" cx="22" cy="22" r="18" fill="none" stroke="url(#pf-green)" stroke-width="5" stroke-linecap="round" pathLength="100" stroke-dasharray="'.$pct.' 100" transform="rotate(-90 22 22)"/></svg><b>'.$pct.'%</b></span>';}

/* 8 · Reading buddy in the corner */
function pf_helper(array $u):string{
 $first=explode(' ',trim($u['name']))[0];
 $lines=['You can do it, '.$first.'!','Reading makes you stronger!','One more story today?','I am proud of you!','Let’s read together!','Every page is a new adventure!','Try your best. That is enough!'];
 return '<div class="pf-buddy"><div class="pf-bubble" role="status" aria-live="polite"></div><button type="button" class="pf-helper" data-pf-helper data-lines="'.e(json_encode($lines)).'" aria-label="Tap your reading buddy for a message">'.pf_kid('96 18 134 112').'</button></div>';
}

/* 9 · Sky that matches the time of day */
function pf_sky():string{
 $h=(int)date('G');$p=$h>=5&&$h<12?'m':($h>=12&&$h<17?'a':'e');
 $tree=fn($x,$y,$c,$t='#7a5230')=>'<rect x="'.($x-1.5).'" y="'.$y.'" width="3" height="8" fill="'.$t.'"/><circle cx="'.$x.'" cy="'.($y-2).'" r="7" fill="'.$c.'"/>';
 $house=fn($x,$y,$w,$r,$win)=>'<rect x="'.$x.'" y="'.$y.'" width="20" height="14" fill="'.$w.'"/><path d="M'.($x-3).' '.$y.'l13-10 13 10z" fill="'.$r.'"/><rect class="'.($p==='e'?'pf-window':'').'" x="'.($x+7).'" y="'.($y+4).'" width="6" height="5" fill="'.$win.'"/>';
 $cloud=fn($x,$y,$s,$c,$cls='pf-drift')=>'<g class="'.$cls.'"><path transform="translate('.$x.' '.$y.') scale('.$s.')" d="M0 14a10 10 0 0 1 16-9 13 13 0 0 1 24 3 8 8 0 0 1 2 16H4a9 9 0 0 1-4-10z" fill="'.$c.'"/></g>';
 $hills=fn($c1,$c2,$x)=>'<path d="M-20 92q70-40 140-14t210-8v40H-20z" fill="'.$c1.'"/>'.$x.'<path d="M-20 102q90-22 180-6t180-8v22H-20z" fill="'.$c2.'"/>';
 $s='<svg class="identity-art pf-sky pf-sky-'.$p.'" viewBox="0 0 320 110" preserveAspectRatio="xMaxYMax slice" role="img" aria-label="'.($p==='m'?'A sunny morning sky':($p==='a'?'A warm afternoon sky':'A starry evening sky')).'"><rect width="320" height="110" fill="url(#pf-sky'.$p.')"/>';
 if($p==='m'){$s.='<circle cx="262" cy="36" r="40" fill="url(#pf-glow)"/><g class="pf-spin"><path d="M262 4v8M262 60v8M230 36h8M286 36h8M240 14l6 6M278 52l6 6M240 58l6-6M278 20l6-6" stroke="#ffd23f" stroke-width="3.5" stroke-linecap="round"/></g><circle cx="262" cy="36" r="17" fill="url(#pf-sun)"/>'.$cloud(176,14,.9,'#fff').$cloud(60,40,.6,'#ffffffcc','pf-drift pf-d2').'<g class="pf-birds">';foreach([[110,28],[130,20],[150,30]] as [$x,$y])$s.='<path class="pf-bird" d="M'.$x.' '.$y.'q4-4 8 0q4-4 8 0" stroke="#24506e" stroke-width="1.8" fill="none" stroke-linecap="round"/>';$s.='</g>'.$hills('#a6dc8f','#6fbf5c',$tree(40,80,'#4c9a52').$tree(54,84,'#5cb85c').$house(220,74,'#fff8e8','#d6452f','#8fd3ff'));}
 elseif($p==='a')$s.='<g class="pf-sink"><circle cx="250" cy="74" r="46" fill="url(#pf-glow)"/><circle cx="250" cy="74" r="22" fill="#ffc35a"/></g>'.$cloud(150,20,1,'#ffd1c2').$cloud(200,46,.7,'#ffb8a6','pf-drift pf-d2').$cloud(40,30,.6,'#ffe1d6').$hills('#c98a6a','#8c5a4a',$tree(70,80,'#6b4a3a','#5a3a2a').$tree(84,84,'#7a5545','#5a3a2a').$house(210,74,'#f4d6c4','#9c3b2a','#ffd772'));
 else{foreach([[30,20,1.6],[70,46,1.2],[110,14,1.8],[150,36,1.2],[190,12,1.5],[296,60,1.3],[130,62,1],[60,74,1.1],[220,52,1.2],[16,52,1]] as $i=>[$x,$y,$r])$s.='<circle class="pf-tw pf-t'.($i%3).'" cx="'.$x.'" cy="'.$y.'" r="'.$r.'" fill="#fff"/>';$s.='<path class="pf-shoot" d="M60 10l40 14" stroke="#fff" stroke-width="2" stroke-linecap="round"/><circle cx="262" cy="34" r="34" fill="url(#pf-glow)" opacity=".5"/><circle cx="262" cy="34" r="17" fill="url(#pf-moon)"/><circle cx="270" cy="28" r="15" fill="#1d2b5c"/>'.$hills('#21324f','#15223a',$tree(60,80,'#0f1a2e','#0f1a2e').$tree(74,84,'#132036','#132036').$house(214,74,'#2c3d63','#1a2440','#ffd772'));}
 return $s.'</svg>';
}

/* 10 · Badge shelf */
function pf_badge_shelf(int $pid):string{
 $out='<div class="pf-shelf">';
 foreach(rows('SELECT b.*,p.earned_at FROM badges b LEFT JOIN pupil_badges p ON p.badge_id=b.id AND p.pupil_id=? WHERE b.active=1 ORDER BY p.earned_at IS NULL,p.earned_at,b.id',[$pid]) as $i=>$b){$got=(bool)$b['earned_at'];
  $out.='<article class="pf-shelf-item '.($got?'pf-got':'pf-locked').'">'.'<div class="pf-shelf-medal">'.pf_medal($b['rule_type'],76,$got).($got?'<span class="pf-shine"></span>':'').'</div><h2>'.e($b['title']).'</h2><p>'.e($b['description']).'</p><small>'.($got?icon('check').'Earned '.e(date('M j, Y',strtotime((string)$b['earned_at']))):icon('lock').'Not yet · keep going!').'</small></article>';}
 return $out.'</div>';
}
